# Exercise 1

```c++
#include <iostream>
#include <cmath>

using namespace std;

double area(double x1, double y1, double x2, double y2) {
    double area = (pow(x2 - x1, 2)) * (pow(y2 - y1, 2));
    return area;
}

double perimeter(double x1, double y1, double x2, double y2) {
    double perimeter = (2 * (x2 - x1)) * (y2 - y1);
    return perimeter;
}

int main() {
    double x1, y1, x2, y2;
    cout << "Enter the two sides of a triangle: ";
    cin >> x1 >> y1 >> x2 >> y2;
    cout << "The area is: " << area(x1, y1, x2, y2) << endl;
    cout << "The perimeter is: " << perimeter(x1, y1, x2, y2) << endl;
    return 0;
}
```

